package com.gireesh.brokerage.entity;
import jakarta.persistence.*; import jakarta.validation.constraints.*; import java.time.LocalDateTime;
@Entity @Table(name="alerts", indexes={@Index(name="idx_alert_account",columnList="account_id"),@Index(name="idx_alert_unread",columnList="account_id,read")})
public class Alert { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @NotNull @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="account_id",nullable=false) private TradingAccount account; @NotNull @Enumerated(EnumType.STRING) @Column(nullable=false) private AlertType type; @NotBlank @Size(max=1000) @Column(nullable=false,length=1000) private String message; @Column(nullable=false) private boolean read; @Column(nullable=false,updatable=false) private LocalDateTime createdAt; private LocalDateTime updatedAt; @PrePersist void create(){createdAt=LocalDateTime.now();updatedAt=createdAt;} @PreUpdate void update(){updatedAt=LocalDateTime.now();} public Alert(){} public Long getId(){return id;} public TradingAccount getAccount(){return account;} public void setAccount(TradingAccount v){account=v;} public AlertType getType(){return type;} public void setType(AlertType v){type=v;} public String getMessage(){return message;} public void setMessage(String v){message=v;} public boolean isRead(){return read;} public void setRead(boolean v){read=v;} public LocalDateTime getCreatedAt(){return createdAt;} public LocalDateTime getUpdatedAt(){return updatedAt;} }
